#!/usr/bin/env node
/* verify/bases.js: every base size in the app is GW's, as GW's base size guide prints it.
   For every stats row (a model of a unit) of every list, the row's base is looked up in GW's base size guide (the Event
   Companion, verify/base-guide.js: lookup) under the faction's sections (verify/sources/factions.json `baseGuide`, else the
   datasheet's faction name) by its datasheet's name and the model's, and must equal it as the app writes it: GW's wording
   ("Oval", "Hull"), × for GW's x, the mm as GW prints it, without the word "Base" ("170×109mm Oval").
   A row the guide has under another name or section, or not at all, is declared in verify/deviations-bases.json:
     guide: { section, entry }   the guide's row for it (compared as any other)
     guide: null                 the guide has none: the app's base (app) is Wahapedia's datasheet's (waha: the cached page,
                                 compared), and the guide must still have no row for it
   with its reason and evidence. Fails on any difference, an undeclared missing row, or a declaration nothing uses.
     node verify/bases.js         check (verify/out/bases.json: every row, its guide line or declaration) */
'use strict';
const fs = require('fs'), path = require('path');
const ROOT = path.join(__dirname, '..');
const T = require('./tables'), G = require('./base-guide');
const FJ = JSON.parse(fs.readFileSync(path.join(ROOT, 'verify/sources/factions.json'), 'utf8'));
const DEVF = 'verify/deviations-bases.json';
const DEVS = JSON.parse(fs.readFileSync(path.join(ROOT, DEVF), 'utf8'));
// the forms GW's guide prints, as the app writes them
const FORM = /^(\d+(\.\d+)?mm|\d+(\.\d+)?×\d+(\.\d+)?mm Oval|Hull|(Large|Small) Flying)$/;
const baseName = n => String(n).replace(/ ×\d+$/, '');

const guide = G.guide();
if (!guide.file) { console.log('FAIL bases: GW’s base size guide is not cached (verify/.cache/gw/*event_companion*.txt)'); process.exit(1); }

const src = fs.readFileSync(path.join(ROOT, 'data.js'), 'utf8');
const D = T.evaluate(src), R = T.read(src), S = R.S ? R.S.value : {};
// which datasheet (and row of it) each stats row of each unit comes from
const from = new Map();
T.resolveArmies(R.A.value, S, R.order, { trace: (a, u, kind, n, sid, j) => { if (kind === 'stats') from.set(a.id + '/' + u.id + '/' + n, sid); } });

const fails = [], rows = [], used = new Set();
const fail = (where, msg) => fails.push(where + ': ' + msg);
const wahaBase = f => { try { const m = /\(&#8960;([^)]*)\)|\(⌀([^)]*)\)/.exec(fs.readFileSync(path.join(ROOT, f), 'utf8')); return m ? (m[1] || m[2]).replace(/\s*x\s*/gi, '×').trim() : null; } catch (e) { return null; } };
for (const a of D.armies) for (const u of a.units) (u.stats || []).forEach((row, n) => {
  const sid = from.get(a.id + '/' + u.id + '/' + n), ds = S[sid];
  const model = baseName(row.name), unit = ds ? ds.name : u.name, fac = ds ? ds.faction : a.faction;
  const where = a.id + ' · ' + u.name + (model !== unit ? ' · ' + model : '');
  const sections = (FJ[fac] || {}).baseGuide || (D.factions[fac] || {}).name || fac;
  const app = row.base;
  const rec = { army: a.id, unit: u.id, datasheet: sid || null, model, app };
  rows.push(rec);
  const dev = DEVS.find(x => x.datasheet === sid && x.row === model);
  const L = G.lookup(sections, [unit, model], unit);
  if (dev) {
    used.add(dev);
    if (!dev.reason || !dev.evidence) fail(where, DEVF + ': its declaration has no reason or evidence');
    if (dev.guide) {
      const e = (guide.factions[dev.guide.section] || []).find(r => r.name === dev.guide.entry);
      if (!e) { fail(where, DEVF + ' names the guide’s row "' + dev.guide.entry + '" (' + dev.guide.section + '), which the guide does not have'); return; }
      if (L) fail(where, DEVF + ' names the guide’s row "' + dev.guide.entry + '", but the guide’s lookup now finds "' + L.entry + '" (line ' + L.line + '): drop the declaration');
      Object.assign(rec, { gw: e.base, line: e.line, entry: e.name, how: 'declared' });
      if (app !== e.base) fail(where, 'app ' + app + ', GW ' + e.base + ' (' + guide.file + ' line ' + e.line + ': "' + e.name + '  ' + e.printed + '", declared in ' + DEVF + ')');
    } else {
      if (L) fail(where, DEVF + ' says GW’s guide has no row, but it has "' + L.entry + '  ' + L.printed + '" (line ' + L.line + '): drop the declaration');
      const w = dev.waha ? wahaBase(dev.waha) : null;
      Object.assign(rec, { gw: null, waha: w, how: 'declared: not in the guide' });
      if (app !== dev.app) fail(where, 'app ' + app + ', declared (' + DEVF + ') ' + dev.app);
      // (no guide row to compare with: the app's base must still be written as the guide writes its bases)
      if (!FORM.test(String(app || ''))) fail(where, 'base "' + app + '" is not in a form GW’s guide prints (e.g. "40mm", "170×109mm Oval", "Hull")');
      if (!dev.waha || w !== dev.app) fail(where, DEVF + ': Wahapedia’s datasheet (' + (dev.waha || 'none named') + ') has ' + w + ', the declaration ' + dev.app);
    }
    return;
  }
  if (!L) { fail(where, 'GW’s base size guide has no row for it (sections ' + [].concat(sections).join(', ') + '; app ' + app + '): declare it in ' + DEVF + ' with its evidence'); return; }
  Object.assign(rec, { gw: L.base, line: L.line, entry: L.entry, how: L.how });
  if (app !== L.base) fail(where, 'app ' + app + ', GW ' + L.base + ' (' + L.file + ' line ' + L.line + ': "' + L.entry + '  ' + L.printed + '")');
});
for (const d of DEVS) if (!used.has(d)) fail(DEVF, 'nothing in the lists matches the declaration for ' + d.datasheet + ' · ' + d.row);

fs.mkdirSync(path.join(ROOT, 'verify/out'), { recursive: true });
fs.writeFileSync(path.join(ROOT, 'verify/out/bases.json'), JSON.stringify({ guide: guide.file, checked: rows.length, failures: fails, rows }, null, 1) + '\n');
if (fails.length) { console.log('FAIL bases: ' + fails.length + ' of ' + rows.length + ' model rows\n' + fails.map(x => ' - ' + x).join('\n')); process.exit(1); }
const nDecl = rows.filter(r => /^declared/.test(r.how)).length;
console.log('bases: ' + rows.length + ' model rows in ' + D.armies.length + ' lists have GW’s base as its guide prints it (' + guide.file.replace(/^.*\//, '') + '; ' + nDecl + ' by a declaration in ' + DEVF + ', ' + rows.filter(r => r.how === 'declared: not in the guide').length + ' of them Wahapedia’s where the guide has none)');

#!/usr/bin/env node
/* verify/base-guide.js: GW's base size guide (the Event Companion, verify/.cache/gw/*event_companion*.txt, `pdftotext -layout`),
   read as { faction (as GW prints it, upper case): [{ name, base, line }] }, and the base size of a unit by its names.

     const G = require('./base-guide');
     G.guide()                               every faction's rows, and the file they come from
     G.lookup('Adeptus Custodes', ['Caladius Annihilator Grav-tank'])
        -> { base:'170×109mm Oval', printed:'170x109mm Oval Base', entry:'Caladius Grav-tank', line:2625, file, how } | null

   A unit is found by the first of its names (datasheet name, then model names) that matches an entry, in this order:
     model          a row for some models of the unit ("Neurogaunts: Nodebeasts"): the unit's name as for plural/squad, and
                    a model name the same, the same as for plural/squad, or all of its words in the row's name
                    ("Jakhals: Dishonoured" for "Dishonoured w/ paired manglers", "Nodebeasts" for "Neurogaunt Nodebeast")
     exact          the same name (quotes, dashes and case alike), a model's own name first ("Sir Hekhtur" before
                    "Canis Rex", the datasheet he is on)
     model of       a model's own name, in the one row of another unit that names it ("Dark Apostle: Dark Disciple" for the
                    Dark Disciples of an attached unit, "Gretchin: Runtherd" for the Runtherd)
     plural/squad   the same once a trailing "s" and the word "Squad" are dropped ("Prosecutor Squad" = "Prosecutors")
     words          every word of the entry is a word of the name, and no other entry of the faction does that with
                    more words ("Caladius Grav-tank" in "Caladius Annihilator Grav-tank")
   The app writes the base as GW prints it, with × for x and without the word "Base" ("170×109mm Oval").
   node verify/base-guide.js "<faction>" "<unit name>" [...]   prints the lookup */
'use strict';
const fs = require('fs'), path = require('path');
const DIR = path.join(__dirname, '.cache/gw');
let CACHE = null;

const norm = s => String(s || '').normalize('NFC').replace(/[’‘ʼ′`]/g, "'").replace(/[‐‑‒–—−]/g, '-').replace(/\s+/g, ' ').trim().toLowerCase();
const words = s => norm(s).split(/[\s-]+/).filter(Boolean);
const loose = s => words(s).filter(w => w !== 'squad').map(w => w.replace(/s$/, '')).join(' ');
const appBase = s => String(s).replace(/\s+Base$/i, '').replace(/(\d)\s*x\s*(\d)/gi, '$1×$2').trim();

// "Wardens of Ultramar: Ancient Gadriel, Veteran Sergeant Metaurus": the unit, and the models of it this row is for
function modelsOf(name) {
  const m = /^([^:]+):\s*(.*)$/.exec(name); if (!m) return null;
  return { unit: m[1].trim(), models: m[2].split(/\s*,\s*/).map(x => x.trim()).filter(Boolean) };
}
function guide() {
  if (CACHE) return CACHE;
  const f = fs.existsSync(DIR) && fs.readdirSync(DIR).filter(x => /event_companion.*\.txt$/.test(x)).sort().pop();
  if (!f) return (CACHE = { file: null, factions: {} });
  const lines = fs.readFileSync(path.join(DIR, f), 'utf8').split('\n');
  const start = lines.findIndex(l => /^\s*BASE SIZE GUIDE\s*$/.test(l));
  const factions = {};
  let cur = null;
  for (let i = Math.max(0, start); i < lines.length; i++) {
    const t = lines[i].trim();
    if (/^UNIT\s{2,}BASE SIZE$/.test(t)) {
      // the faction's name is the line before the header (a page number there: the same faction goes on)
      const prev = (lines[i - 1] || '').trim();
      if (prev && !/^\d+$/.test(prev)) { cur = prev.toUpperCase(); factions[cur] = factions[cur] || []; }
      continue;
    }
    if (!cur || !t) continue;
    const m = /^(.+?)\s{2,}(\S.*)$/.exec(t);
    // a line that goes on from the one before ("Wardens of Ultramar: Gaius Silva, …, Dainal Kornelius," / "Lucia Vestha")
    const prevRow = factions[cur][factions[cur].length - 1];
    if (!m && prevRow && prevRow.line === i && /,$/.test(prevRow.name)) { prevRow.name += ' ' + t; prevRow.models = modelsOf(prevRow.name); prevRow.line = i + 1; prevRow.lines = [prevRow.first, i + 1]; continue; }
    if (!m || !/\d+mm|Hull|Base|Flying/i.test(m[2])) continue;
    factions[cur].push({ name: m[1].trim(), printed: m[2].trim(), base: appBase(m[2].trim()), line: i + 1, first: i + 1, models: modelsOf(m[1].trim()) });
  }
  return (CACHE = { file: 'verify/.cache/gw/' + f, factions });
}

// faction: GW's section name, or a list of them (an Ultramarines list: SPACE MARINES, DEATHWATCH); unit: the datasheet's name, when
// names[1] is one model of it (a row for some models of a unit: "Wardens of Ultramar: Gaius Silva, Aemelia Minervas, …")
function lookup(faction, names, unit) {
  const G = guide(), facs = [].concat(faction), rows = [];
  for (const f of facs) { const key = Object.keys(G.factions).find(k => norm(k) === norm(f)); if (key) rows.push(...G.factions[key]); }
  if (!rows.length) return null;
  const hit = (e, how, n) => Object.assign({}, e, { entry: e.name, file: G.file, how, for: n, line: e.first || e.line });
  const all = names.filter(Boolean), own = unit ? all.filter(n => norm(n) !== norm(unit)) : all;
  // a model of a row for some models: the same, the same as for plural/squad, or all of its words in the name
  const wset = n => new Set(words(n).map(w => w.replace(/s$/, '')));
  const modelIs = [(x, n) => norm(x) === norm(n), (x, n) => loose(x) === loose(n), (x, n) => { const nw = wset(n); return words(x).every(w => nw.has(w.replace(/s$/, ''))); }];
  if (unit) for (const is of modelIs) for (const n of all) {
    const e = rows.find(r => r.models && loose(r.models.unit) === loose(unit) && r.models.models.some(x => is(x, n)));
    if (e) return hit(e, 'model', n);
  }
  for (const n of own) {
    const e = rows.find(r => norm(r.name) === norm(n)); if (e) return hit(e, 'exact', n);
  }
  const modelOf = n => { const ok = rows.filter(r => r.models && r.models.models.some(x => norm(x) === norm(n))); return ok.length === 1 ? hit(ok[0], 'model of ' + ok[0].models.unit, n) : null; };
  for (const n of own) { const e = modelOf(n); if (e) return e; }
  for (const n of all) {
    const e = rows.find(r => norm(r.name) === norm(n)); if (e) return hit(e, 'exact', n);
  }
  for (const n of all) {
    const e = rows.find(r => loose(r.name) === loose(n)); if (e) return hit(e, 'plural/squad', n);
  }
  for (const n of names.filter(Boolean)) {
    const nw = new Set(words(n).map(w => w.replace(/s$/, '')));
    const ok = rows.filter(r => !r.models && words(r.name).every(w => nw.has(w.replace(/s$/, '')))).sort((a, b) => words(b.name).length - words(a.name).length);
    if (ok.length && (ok.length === 1 || words(ok[0].name).length > words(ok[1].name).length) && words(ok[0].name).length >= 2) return hit(ok[0], 'words', n);
  }
  for (const n of all) { const e = modelOf(n); if (e) return e; }
  return null;
}

module.exports = { guide, lookup, appBase };
if (require.main === module) {
  const [fac, ...names] = process.argv.slice(2);
  console.log(JSON.stringify(lookup(fac.split(','), names, names[0]), null, 1));
}
